86	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
87	    @Override
88	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
89	        Collection<Owner> owners;
90	        if (lastName != null) {
91	            owners = this.clinicService.findOwnerByLastName(lastName);
92	        } else {
93	            owners = this.clinicService.findAllOwners();
94	        }
95	        if (owners.isEmpty()) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
104	        Owner owner = this.clinicService.findOwnerById(ownerId);
105	        if (owner == null) {
106	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
107	        }
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
110	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = normalizeAddress(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        if (owner.getEmail() != null) {
128	            String email = normalizeEmail(owner.getEmail());
129	            if (email == null) {
130	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
131	            }
132	            owner.setEmail(email);
133	            for (Owner existing : this.clinicService.findAllOwners()) {
134	                if (existing.getEmail() != null && email.equalsIgnoreCase(existing.getEmail())) {
135	                    return new ResponseEntity<>(HttpStatus.CONFLICT);
136	                }
137	            }
138	        }
139	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
140	        if (effectiveRegistrationDate == null) {
141	            effectiveRegistrationDate = LocalDate.now();
142	        }
143	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
144	        owner.setRegistrationDate(registrationDate);
145	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
146	            return new ResponseEntity<>(HttpStatus.CONFLICT);
147	        }
148	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
149	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
150	        }
151	        for (Owner existing : this.clinicService.findAllOwners()) {
152	            if (telephone.equals(toE164(existing.getTelephone()))) {
153	                return new ResponseEntity<>(HttpStatus.CONFLICT);
154	            }
155	        }
156	        String lastNameKey = householdKey(owner.getLastName());
157	        String addressKey = householdKey(owner.getAddress());
158	        List<Owner> householdMembers = new ArrayList<>();
159	        for (Owner existing : this.clinicService.findAllOwners()) {
160	            if (lastNameKey.equals(householdKey(existing.getLastName()))
161	                && addressKey.equals(householdKey(existing.getAddress()))) {
162	                householdMembers.add(existing);
163	            }
164	        }
165	        if (!householdMembers.isEmpty()) {
166	            if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
167	                return new ResponseEntity<>(HttpStatus.CONFLICT);
168	            }
169	            String householdId = householdId(lastNameKey, addressKey);
170	            owner.setHouseholdId(householdId);
171	            for (Owner member : householdMembers) {
172	                if (!householdId.equals(member.getHouseholdId())) {
173	                    member.setHouseholdId(householdId);
174	                    this.clinicService.saveOwner(member);
175	                }
176	            }
177	        }
178	        owner.setTelephone(telephone);
179	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
180	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
181	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
182	        this.clinicService.saveOwner(owner);
183	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
184	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
185	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
186	            ownerDto.getMembershipLevel());
187	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
188	        headers.setLocation(UriComponentsBuilder.newInstance()
189	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
190	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
191	    }
