271	
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
276	        Owner owner = this.clinicService.findOwnerById(ownerId);
277	        if (owner != null) {
278	            Pet pet = owner.getPet(petId);
279	            if (pet != null) {
280	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
281	            }
282	        }
283	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
284	    }
285	
286	    /**
287	     * The maximum number of owners permitted per city. Owner creation is rejected once the
288	     * owner's city already contains this many owners.
289	     */
290	    private static final int MAX_OWNERS_PER_CITY = 50;
291	
292	    /**
293	     * Counts how many existing owners live in the given city, compared case-insensitively.
294	     * This is evaluated before the new owner is persisted, so the owner being created is not
295	     * included in the count.
296	     *
297	     * @param city the new owner's city
298	     * @return the number of existing owners in that city
299	     */
300	    private int countOwnersInCity(String city) {
301	        int count = 0;
302	        for (Owner existing : this.clinicService.findAllOwners()) {
303	            if (city.equalsIgnoreCase(existing.getCity())) {
304	                count++;
305	            }
306	        }
307	        return count;
308	    }
309	
310	    /**
311	     * The maximum number of owners that may be created in a single business day. Owner
312	     * creation is rejected once this many owners already fall on the new owner's adjusted
313	     * business day {@code registrationDate}.
314	     */
315	    private static final int MAX_OWNERS_PER_DAY = 100;
316	
317	    /**
318	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
319	     * to the following Monday, while a weekday is returned unchanged.
320	     *
321	     * @param date the date to adjust
322	     * @return the same date if it is a weekday, otherwise the following Monday
323	     */
324	    private LocalDate toBusinessDay(LocalDate date) {
325	        DayOfWeek dayOfWeek = date.getDayOfWeek();
326	        if (dayOfWeek == DayOfWeek.SATURDAY) {
327	            return date.plusDays(2);
328	        }
329	        if (dayOfWeek == DayOfWeek.SUNDAY) {
330	            return date.plusDays(1);
331	        }
332	        return date;
333	    }
334	
335	    /**
336	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
337	     * registrationDate} rolls forward to the same business day. This is evaluated before the
338	     * new owner is persisted, so the owner being created is not included in the count.
339	     *
340	     * @param businessDay the adjusted business day to count against
341	     * @return the number of existing owners registered on that business day
342	     */
343	    private int countOwnersRegisteredOn(LocalDate businessDay) {
344	        int count = 0;
345	        for (Owner existing : this.clinicService.findAllOwners()) {
346	            LocalDate existingDate = existing.getRegistrationDate();
347	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
348	                count++;
349	            }
350	        }
351	        return count;
352	    }
353	
354	    /**
355	     * The number of owners that may be created on a single business day before a bulk-signup
356	     * warning is raised. Once more than this many owners already fall on the current business
357	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
358	     */
359	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
360	
361	    /**
362	     * Reports whether an unusually high number of owners have been created for today's business
363	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
364	     * the business day that {@code LocalDate.now()} rolls forward to.
365	     *
366	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
367	     */
368	    private boolean isBulkSignupDay() {
369	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
370	    }
371	
372	    /**
373	     * Builds the customer code for a newly created owner, formatted
374	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
375	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
376	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
377	     * to one more than the number of owners already in that city.
378	     *
379	     * @param city     the owner's city
380	     * @param lastName the owner's last name
381	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
382	     */
383	    private String nextCustomerCode(String city, String lastName) {
384	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
385	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
386	        int sequence = 1;
387	        for (Owner existing : this.clinicService.findAllOwners()) {
388	            if (city.equalsIgnoreCase(existing.getCity())) {
389	                sequence++;
390	            }
391	        }
392	        return String.format("%s-%s-%04d", city3, last3, sequence);
393	    }
394	
395	    /**
396	     * Builds the membership number for a newly created owner, formatted
397	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
398	     * customer code and {@code YY} is the last two digits of the owner's registration
399	     * date year, zero-padded to two digits.
400	     *
401	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
402	     * @param registrationDate the owner's registration date
403	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
404	     */
405	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
406	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
407	    }
408	
409	    /**
410	     * Counts how many existing owners share the given first and last name, compared
411	     * case-insensitively. This is evaluated before the new owner is persisted, so the
412	     * owner being created is not included in the count.
413	     *
414	     * @param firstName the new owner's first name
415	     * @param lastName  the new owner's last name
416	     * @return the number of existing owners with the same first and last name
417	     */
418	    private int countNamesakes(String firstName, String lastName) {
419	        int count = 0;
420	        for (Owner existing : this.clinicService.findAllOwners()) {
421	            if (firstName.equalsIgnoreCase(existing.getFirstName())
422	                && lastName.equalsIgnoreCase(existing.getLastName())) {
423	                count++;
424	            }
425	        }
426	        return count;
427	    }
428	
429	    /**
430	     * Canonical expansions applied to common street-type abbreviations during address
431	     * normalization. Keys and values are upper-cased so the lookup runs after the address
432	     * has itself been upper-cased.
433	     */
434	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
435	        "ST", "STREET",
436	        "RD", "ROAD",
437	        "AVE", "AVENUE");
438	
439	    /**
440	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
441	     * every run of internal whitespace is collapsed to a single space, the result is
442	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
443	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
444	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
445	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
446	     * returned and compared for household duplicates; an address that is blank once
447	     * normalized fails the required-field check.
448	     *
449	     * @param address the raw address value supplied by the client
450	     * @return the normalized address (empty string when {@code address} is null or blank)
451	     */
452	    private static String normalizeAddress(String address) {
453	        if (address == null) {
454	            return "";
455	        }
456	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
457	        if (collapsed.isEmpty()) {
458	            return "";
459	        }
460	        StringBuilder normalized = new StringBuilder(collapsed.length());
461	        for (String token : collapsed.split(" ")) {
462	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
463	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
464	            if (normalized.length() > 0) {
465	                normalized.append(' ');
466	            }
467	            normalized.append(expanded != null ? expanded : token);
468	        }
469	        return normalized.toString();
470	    }
471	
472	    /**
473	     * Normalizes a last name or address for household-duplicate comparison: leading and
474	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
475	     * single space and the result is lower-cased. Two owners are considered to share a
476	     * household when both their last names and addresses produce the same key.
477	     *
478	     * @param value the raw last name or address value
479	     * @return the normalized comparison key (empty string when {@code value} is null)
480	     */
481	    private static String householdKey(String value) {
482	        if (value == null) {
483	            return "";
484	        }
485	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
486	    }
487	
488	    /**
489	     * Derives the stable shared household identifier for the given normalized last name
490	     * and address keys. The identifier is deterministic — the same household (same
491	     * {@link #householdKey normalized} last name and address) always maps to the same
492	     * value — so every owner who joins a household is assigned an identical id. It is the
493	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
494	     * '<lastNameKey>|<addressKey>'}.
495	     *
496	     * @param lastNameKey the normalized last name key
497	     * @param addressKey  the normalized address key
498	     * @return the shared household identifier
499	     */
500	    private static String householdId(String lastNameKey, String addressKey) {
501	        String source = lastNameKey + "|" + addressKey;
502	        try {
503	            byte[] digest = MessageDigest.getInstance("SHA-256")
504	                .digest(source.getBytes(StandardCharsets.UTF_8));
505	            StringBuilder hex = new StringBuilder(digest.length * 2);
506	            for (byte b : digest) {
507	                hex.append(String.format("%02x", b));
508	            }
509	            return hex.substring(0, 12).toUpperCase();
510	        } catch (NoSuchAlgorithmException e) {
511	            throw new IllegalStateException("SHA-256 not available", e);
512	        }
513	    }
514	
515	    /**
516	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
517	     * and brackets are stripped. When the number already carries a leading {@code '+'}
518	     * and country code these are kept; a number written in national trunk form (a leading
519	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
520	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
521	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
522	     * after the {@code '+'}, and its national-number length must be valid for the detected
523	     * country code (see {@link #hasValidNationalLength}).
524	     *
525	     * @param telephone the raw telephone value supplied by the client
526	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
527	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
528	     */
529	    private static String toE164(String telephone) {
530	        if (telephone == null) {
531	            return null;
532	        }
533	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
534	        String digits;
535	        if (cleaned.startsWith("+")) {
536	            digits = cleaned.substring(1);
537	        } else if (cleaned.startsWith("0")) {
538	            digits = "61" + cleaned.substring(1);
539	        } else {
540	            digits = "1" + cleaned;
541	        }
542	        if (!digits.matches("[0-9]{8,15}")) {
543	            return null;
544	        }
545	        if (!hasValidNationalLength(digits)) {
546	            return null;
547	        }
548	        return "+" + digits;
549	    }
550	
551	    /**
552	     * Validates the national-number length of an E.164 digit string against its country
553	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
554	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
555	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
556	     *
557	     * @param digits the E.164 digits (without the leading {@code '+'})
558	     * @return {@code true} when the national-number length is valid for the country code
559	     */
560	    private static boolean hasValidNationalLength(String digits) {
561	        if (digits.startsWith("61")) {
562	            return digits.length() - 2 == 9;
563	        }
564	        if (digits.startsWith("1")) {
565	            return digits.length() - 1 == 10;
566	        }
567	        return true;
568	    }
569	
570	    /**
571	     * Normalizes an owner email for creation. A present email must be a syntactically
572	     * valid address; the returned value is lower-cased.
573	     *
574	     * @param email the raw email value supplied by the client (never {@code null} here)
575	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
576	     *         address (signalling a 400 Bad Request)
577	     */
578	    private static String normalizeEmail(String email) {
579	        String trimmed = email.trim();
580	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
581	            return null;
582	        }
583	        return trimmed.toLowerCase();
584	    }
585	}
